            PopulateTreeView(treeView, property.Value, property.Name);
            treeViewItem.Items.Add(new TreeViewItem
            {
                Header = $"{property.Name}: {GetTokenDisplayValue(property.Value)}"
            });
        }
    }
    else if (token is JArray jArray)
    {
        for (int i = 0; i < jArray.Count; i++)
        {
            treeViewItem.Items.Add(new TreeViewItem
            {
                Header = $"[{i}]: {GetTokenDisplayValue(jArray[i])}"
            });
        }
    }

    treeView.Items.Add(treeViewItem);
}

// Get a display value for a JSON token
private string GetTokenDisplayValue(JToken token)
{
    if (token is JValue jValue)
    {
        return jValue.ToString();
    }
    else if (token is JObject)
    {
        return "{...}";
    }
    else if (token is JArray)
    {
        return "[...]";
    }
    return token.ToString();
}
